from pathlib import Path
import hashlib,importlib.util,json,re
root=Path.cwd();base=root/'tests/fixtures/consumer'
spec=importlib.util.spec_from_file_location('catalogue',root/'tools/goway_catalogue.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
symbols=m.generated_symbols(root)
census=json.loads((root/'tests/fixtures/goway/testdata/oracles/comparisons.json').read_text())['files']
rows=[];methods=[];generated=[];directives=[]
for p in sorted(base.rglob('*.go')):
 s=p.read_text();rel=str(p.relative_to(root))
 if p.name.endswith('_foundry.gen.go'):
  if 'FoundryModel' in s or 'ProjectionDefinition[' in s:generated.append(rel)
  continue
 for i,line in enumerate(s.splitlines(),1):
  if line.startswith('//foundry:model') or line.startswith('//foundry:projection'):directives.append({'file':rel,'line':i,'directive':line})
 code=m.code_only(s);refs=set()
 for alias,path in re.findall(r'(?:\b([A-Za-z_]\w*)\s+)?"([^"\n]+)"',s):
  qualifier=alias or path.rsplit('/',1)[-1]
  selected=set(re.findall(r'\b'+re.escape(qualifier)+r'\s*\.\s*([A-Za-z_]\w*)',code))
  refs.update(qualifier+'.'+symbol for symbol in selected & symbols.get(path,set()))
 own='foundry.test/consumer/'+str(p.parent.relative_to(base))
 refs.update(n for n in symbols.get(own,set()) if re.search(r'(?<![\w.])'+re.escape(n)+r'\b',code))
 boundary=sorted(set(re.findall(r'\bFoundry(?:Reference|Identity|Model|CreateMutation|UpdateMutation)\s*(?=\()',code)))
 if boundary:methods.append({'file':rel,'names':boundary})
 if not refs:continue
 paired=census.get('consumer/'+str(p.relative_to(base)),{}).get('paired_tests',[])
 category='oracle_recording' if paired else 'compilefail' if '/testdata/compilefail/' in rel else 'other'
 rows.append({'file':rel,'category':category,'symbols':sorted(refs),'paired_tests':paired,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
result={'base':'dbe6b1b7','method':'Exact exported model/projection symbols indexed by tools/goway_catalogue.py, matched against imported package aliases and unqualified same-package uses after masking comments and strings. Oracle recording files come from the existing comparisons.json paired_tests census. Generated implementations and ambiguous receiver boundaries are inventoried separately.','generated_files':generated,'directives':directives,'references':rows,'receiver_boundary_candidates':methods}
Path('/private/tmp/goway-d-helper-exact-audit.json').write_text(json.dumps(result,indent=2)+'\n')
for category in ['oracle_recording','compilefail','other']:
 group=[r for r in rows if r['category']==category];print(category, len(group))
 if category=='other':
  for r in group:print(' ',r['file'],', '.join(r['symbols']))
print('generated_files',len(generated),'directives',len(directives))
print('receiver_boundaries',len(methods))
